// RemoveHeroMedium relationship.
// Sets o.R.HeroMedium to nil.
// Removes o from all passed in related items' relationships struct.
func (o *Event) RemoveHeroMedium(ctx context.Context, exec boil.ContextExecutor, related *MediaAsset) error {
	var err error

	queries.SetScanner(&o.HeroMediaID, nil)
	if _, err = o.Update(ctx, exec, boil.Whitelist("hero_media_id")); err != nil {
		return errors.Wrap(err, "failed to update local table")
	}

	if o.R != nil {
		o.R.HeroMedium = nil
	}
	if related == nil || related.R == nil {
		return nil
	}

	for i, ri := range related.R.HeroMediumEvents {
		if queries.Equal(o.HeroMediaID, ri.HeroMediaID) {
			continue
		}

		ln := len(related.R.HeroMediumEvents)
		if ln > 1 && i < ln-1 {
			related.R.HeroMediumEvents[i] = related.R.HeroMediumEvents[ln-1]
		}
		related.R.HeroMediumEvents = related.R.HeroMediumEvents[:ln-1]
		break
	}
	return nil
}

